  const domain = (typeof module !== 'undefined' && module.exports)
    ? require('./domain.js')
    : root.FlagDomain;
  const api = { fnv1a: domain.fnv1a, FeatureFlagController: domain.FeatureFlagController };
  if (typeof module !== 'undefined' && module.exports) {
    module.exports = api;
  }
